window.TEXTP = window.TEXTP || {};
window.TEXTP["92.2"] = [[["p","111/13 – Первый аят:"],["p","Всевышний Аллах сказал: «И одолжайте Аллаху хороший заем [давайте милостыню из своего имущества]. И что вы уготовите вперёд из добра [какое бы благодеяние ни сделали] для самих себя, найдёте это (в День Суда) у Аллаха», сура «Аль-Муззаммиль»/20 аят."],["h2","<b>Глава: Залог</b>"],["p","112/14 – Первый аят:"],["p","Всевышний Аллах сказал: «А если вы будете в пути и не найдете писца (для записи долга, который даётся на определённый срок), то (у получателя долга) берутся залоги (которые даются кредитору, как гарантия уплаты долга)», сура «Аль-Бакара»/283 аят."],["h2","<b>Глава: Гарантии</b>"],["p","113/15 – Первый аят:"],["p","Всевышний Аллах сказал: «Тому, кто принесет её, – (получит в награду) груз верблюда. И я за это отвечаю [ручаюсь за это обещание]», сура «Йусуф»/72 аят."],["sc","img/word-92/image56.webp",296,502,"f"],["c","Книга Торговли"],["h2","<b>Раздел: О доверенности</b>"],["p","114/16 – Первый аят:"],["p","Всевышний Аллах сказал: (Йакуб) сказал: «Не пошлю я его с вами, пока вы не придете с договором от Аллаха [пока не дадите клятвы Аллахом], что непременно приведёте его ко мне (обратно), кроме только (случая) если вас что-нибудь постигнет». И когда они [братья] дали ему их клятвенное обещание, он [Йакуб] ска­зал: «Аллах – покровитель [свидетель и хранитель] тому, что мы говорим!», сура «Йусуф»/66 аят."],["h2","<b>Глава: Примирение сторон</b>"],["p","115/17 – Первый аят:"],["p","Всевышний Аллах сказал: «И если две группы верующих будут сражаться (друг против друга), то примирите их (о, верующие) (призвав их обратиться за решением к Книге Аллаха и Сунне Пророка). Если же один (из них двоих) будет покушаться на другого (после того, как было вынесено решение и не будет доволен им), то сражайтесь против того, который покушается, пока он не вернется к велению Аллаха [к истине]. А если он вернется, то примирите их по справедливости и будьте беспристрастны [строго придерживаясь решения Аллаха и затем Его посланника и не отдавая предпочтений кому-либо]: поистине Аллах любит беспристрастных! (9) Поистине, верующие – братья [в любых вопросах верующие возвращаются к одной основе – Вере]. Так улаживайте же (отношения) (даже уже) между двумя вашими братьями (и тем более примиряйте, когда спорящих и враждующих больше) и остерегайтесь Аллаха (во всех ваших делах), – может быть, вы будете одарены милосердием (Аллаха) (10)», сура «Аль-Худжурат»/9-10 аяты."]],[["p","116/18 – Второй аят:"],["p","Всевышний Аллах сказал: «И (ведь) согласие – лучше», сура «Ан-Ниса»/128 аят."],["h2","<b>Глава: Блокирование денежных средств</b>"],["p","Всевышний Аллах сказал: «А если (должник) окажется в затруднении [не будет способен выплатить долг], то (вам следует проявить) ожидание [дать отсрочку] до облегчения [пока Аллах не облегчит положение должника, что он сможет вернуть вам свой долг]."],["sc","img/word-92/image57.webp",345,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","А дать милостыню [оставить весь долг или часть его должнику] – лучше для вас (и в этом мире и в Вечной жизни), если бы вы (только) знали (это)», сура «Аль-Бакара»/280 аят."],["h2","<b>Раздел: О блокировании денежных средств недееспособного человека</b>"],["p","118/20 – Первый аят:"],["p","Всевышний Аллах сказал: «А когда дети у вас достигнут зрелости (и станут обязанными исполнять обязанности по Вере)», сура «Ан-Нур»/59 аят."],["p","119/21 – Второй аят:"],["p","Всевышний Аллах сказал: «И испытывайте сирот (которые находятся на вашем попечении) (на умение правильно распоряжаться имуществом), пока они не достигнут брачного возраста. А если вы заметите в них правильность [праведность в Вере и умение правильно распоряжаться имуществом], то отдавайте им их имущество. И не пожирайте его [имущество сирот] расточительно и торопливо, пока они не вырастут (и не заберут у вас своего имущества). А кто (из вас) богат, пусть будет воздержан (и ничего не берёт с имущества сироты); а кто (из вас) беден, пусть ест согласно мере [по мере необходимости] (когда вынужден). А когда вы отдаете им [сиротам] их имущество, то берите к ним свидетелей (чтобы застраховать себя от непризнания ими этой передачи). И довольно того, что Аллах ведёт счёт!», сура «Ан-Ниса»/6 аят."],["p","120/22 – Третий аят:"],["p","Всевышний Аллах сказал: «То пусть диктует его опекун [тот, который занимается его делами] (как например, отец, или дед, или брат, или мать и другие)», сура «Аль-Бакара»/282 аят."]],[["p","121/23 – Четвертый аят:"],["p","Всевышний Аллах сказал: «И не давайте (о, попечители) легкомысленным [расточительным] (мужчинам, женщинам и детям) вашего имущества [того, которое находится в ваших руках]», сура «Ан-Ниса»/5 аят."],["p","122/24 – Пятый аят:"],["p","Всевышний Аллах сказал: «И не приближайтесь к имуществу сироты, иначе как с тем, что лучше», сура «Аль-Анам»/152 аят."],["sc","img/word-92/image58.webp",295,502,"f"],["c","Книга Торговли"],["p","123/25 – Шестой аят:"],["p","Всевышний Аллах сказал: «А если вы будете совмещать с ними (ваши житейские дела), то ведь они – ваши братья; Аллах распознает творящего беспорядок [алчно расточающего имущество сироты] от творящего благое. А если бы захотел Аллах, Он бы вас утомил (запретив смешивать имущество сироты с вашим имуществом). Поистине, Аллах – величественный (в Своём владычестве), мудрый (в Своих решениях и повелениях)!», сура «Аль-Бакара»/220 аят."],["p","124/26 – Седьмой аят:"],["p","Всевышний Аллах сказал: «А если вы боитесь, что не будете справедливы с (девушками) сиротами (которые находятся на вашем попечении) (если женитесь на них) (что не сможете отдать им их брачный дар как другим женщинам), то женитесь на (других) (из) тех, что приятны вам, женщинах – на двух, (или) на трёх, (или) на четырёх. А если боитесь, что не будете справедливы (между несколькими жёнами), то (женитесь) (лишь) на одной или на тех, которыми овладели ваши десницы (так как не является обязательным придерживаться полной справедливости между невольницами). Это [женитьба лишь на одной] ближе, чтобы не уклониться (от справедливости)», сура «Ан-Ниса»/3 аят."],["h2","<b>Глава: Уполномочение</b>"],["p","125/27 – Первый аят:"],["p","Всевышний Аллах сказал: «Пошлите одного из вас с этими вашими деньгами в город: пусть он посмотрит, у кого (из жителей города) чище пища [дозволенная и благая], и пусть придёт он к вам с пропитанием от него», сура «Аль-Кахф»/19 аят."]],[["p","126/28 – Второй аят:"],["p","Всевышний Аллах сказал: «Поставь меня (управляющим) над сокровищницами земли [страны]: ведь я – хранитель [могу наилучшим образом сохранить богатства], знающий [умею управлять делами государства]», сура «Йусуф»/55 аят."],["p","127/29 – Третий аят:"],["p","Всевышний Аллах сказал: «Работающих над этим [сборщикам закята]», сура «Ат-Тауба»/60 аят."],["sc","img/word-92/image59.webp",295,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Компаньонство </b>"],["p","128/30 – Первый аят:"],["p","Всевышний Аллах сказал: «И (ведь) поистине, многие из соучастников (по какому-либо делу) злоумышляют друг на друга [покушаются на права другого], кроме только тех, которые уверовали и совершали праведные деяния [кроме праведных верующих] – и их [таких] мало», сура «Сад»/24 аят."],["h2","<b>Раздел: Отправление в путь с целью поиска пропитания</b>"],["p","129/31 – Первый аят:"],["p","Всевышний Аллах сказал: «И другие, которые странствуют по земле, желая обрести (что-либо) от щедрости Аллаха [в поисках пропитания]», сура «Аль-Муззаммиль»/20 аят."],["h2","<b>Глава: Работа по найму</b>"],["p","130/32 – Первый аят:"],["p","Всевышний Аллах сказал: «А если они [разведённые женщины] выкармливают для вас (вашего ребёнка), то (вы) давайте им их плату (за кормление)», сура «Ат-Талак»/6 аят."],["p","131/33 – Второй аят:"],["p","Всевышний Аллах сказал: «А на том, у кого родился [на отце ребёнка], (лежит обязанность обеспечивать) пропитанием их [разведённых кормящих жён] и одеждой согласно принятому (по шариату и среди людей)», сура «Аль-Бакара»/233 аят."],["p","132/34 – Третий аят:"],["p","Всевышний Аллах сказал: «Одна из них сказала: «Отец мой, найми его [Мусу]: ведь лучшим из тех,"],["sc","img/word-92/image60.webp",336,506,"f"],["c","Книга Торговли"]],[["p","кого ты наймёшь [можешь нанять], (будет) сильный [который может охранять скот] и надёжный [которому можно смело доверять]. (Когда отец спросил её: «Откуда ты знаешь, что сильный и надёжный?» Он сказала: «Он поднял камень, закрывающий колодец, который могут поднять только десять мужчин. И когда мы шли домой, он попросил меня, чтобы я шла позади него, чтобы не смотреть на меня») (26) (Их отец) сказал (Мусе): «Поистине, я хочу женить тебя на одной из этих двух моих дочерей с тем (условием), что ты наймёшься ко мне (пасти скот) на восемь лет. А если ты завершишь десятью (годами), так это (будет) (искренним благодеянием) от тебя. И я не хочу затруднять тебя (сделав срок в десять лет). Ты найдёшь меня, если пожелает Аллах, из числа праведных [я буду хорошим товарищем и исполню то, что сказал] (27)», сура «Аль-Касас»/26-27 аяты."],["p","133/35 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Если бы ты хотел, то непременно взял бы за это плату (на которую мы купили бы еды)», сура «Аль-Кахф»/77 аят."],["h2","<b>Глава: Предмет соревнования</b>"],["p","134/36 – Первый аят:"],["p","Всевышний Аллах сказал: «Поистине, Мы пустились бегать вперегонки», сура «Йусуф»/17 аят."],["h2","<b>Глава: Вид торговых сделок «Аль-‘Арайа»</b>"],["p","135/37 – Первый аят:"],["p","Всевышний Аллах сказал: «И помогайте (о, верующие) одни (из вас) другим в благочестии [совершении благих поступков] и остережении (от совершения грехов и ослушаний)», сура «Аль-Маида»/2 аят."],["p","136/38 – Второй аят:"],["p","Всевышний Аллах сказал: «И отказывают в подаянии [отказывает даже в таких простых вещах, как ведро, мотыга, котел, и даже в воде и соли]!», сура «Аль-Маун»/7 аят."],["p","137/39 – Третий аят:"],["p","Всевышний Аллах сказал: «Поистине, Аллах повелевает вам возвращать доверенное имущество владельцам его», сура «Ан-Ниса»/58 аят"],["sc","img/word-92/image61.webp",334,520,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Принуждение</b>"]],[["p","138/40 – Первый аят:"],["p","Всевышний Аллах сказал: «И не поедайте ваши имущества между собой незаконно [пусть одни из вас не посягают на имущество других, не имея на это права]», сура «Аль-Бакара»/188 аят."],["h2","<b>Глава: Вещь, отдаваемая на хранение; вклад; депозит</b>"],["p","139/41 – Первый аят:"],["p","Всевышний Аллах сказал: «А если один из вас доверяет другому, то (не будет греха, если долг не будет записан, и не будут приглашены свидетели и не будет залога и в таком случае долг остаётся на ответственности берущего в долг и) пусть возвращает тот, которому доверено, доверенное [то, что он взял в долг] и пусть остерегается (наказания) Аллаха, Господа своего (и поэтому пусть выполнит свои обязательства перед тем, кто дал ему в долг)», сура «Аль-Бакара»/283 аят."],["h2","<b>Глава: Вознаграждение</b>"],["p","140/42 – Первый аят:"],["p","Всевышний Аллах сказал: «Тому, кто принесет её, – (получит в награду) груз верблюда», сура «Йусуф»/72 аят."],["h2","<b>Глава: Найденное имущество, чей хозяин не известен</b>"],["p","141/43 – Первый аят:"],["p","Всевышний Аллах сказал: «И помогайте (о, верующие) одни (из вас) другим в благочестии [совершении благих поступков]», сура «Аль-Маида»/2 аят."],["h2","<b>Глава: Имущество, завещенное на благотворительные цели (вакуф)</b>"],["p","142/44 – Первый аят:"],["p","Всевышний Аллах сказал: «И творите добро, чтобы вы (этим самым) преуспели», сура «Аль-Хадж»/77 аят."],["sc","img/word-92/image62.webp",296,502,"f"],["c","Книга Торговли"],["h2","<b>Раздел: Об условиях, предъявляемых к завещателю вакуфа</b>"],["p","143/45 – Первый аят:"],["p","Всевышний Аллах сказал: «Наставляет вас Аллах относительно ваших детей: мужчине (даётся) доля (наследства), подобная доле двух женщин», сура «Ан-Ниса»/11 аят."],["p","144/46 – Второй аят:"],["p","Всевышний Аллах сказал: «И даровали Мы ему [пророку Ибрахиму] (сына) Исхака и (внука) Йа'куба; всех Мы наставили на (истинный) путь. И (также) Нуха наставили Мы на истинный путь (ещё) раньше [до Ибрахима, Исхака и Йа'куба], и из потомства его [Нуха] (наставили Мы на истинный путь) – Дауда, Сулаймана, Аййуба, Йусуфа, Мусу и Харуна. И так (как) (даровали Мы этим пророкам наставление на Истинный путь) Мы вознаграждаем искренних [добродеющих]! (84) И (также Мы наставили на истинный путь) Закарийю, Йахью, Иису и Ильяса, – все они (были) из (числа) праведных. (85) И (также Мы наставили на истинный путь) Исмаила, аль-Йас'а, Йунуса и Лута – и всех (этих посланников) Мы превознесли над мирами [над людьми, которые жили с ними в одно время] (86)», сура «Аль-Анам»/84-86 аят."],["h2","<b>Глава: Завещания</b>"]],[["p","145/47 – Первый аят:"],["p","Всевышний Аллах сказал: «Предписано [сделано обязательным] вам, когда предстанет к кому-нибудь из вас смерть [появятся признаки того, что человек умрёт], если он оставляет добро [много имущества], завещаниедля родителей [матери и отца] и (близких) родственников согласно известному [по шариату], как обязательство для остерегающихся (наказания Аллаха)», сура «Аль-Бакара»/180 аят."],["p","146/48 – Второй аят:"],["p","Всевышний Аллах сказал: «(И такое распределение наследственного имущества делается) после (исполнения) завещанного, которое вы завещаете, или долга (который есть на вас)», сура «Ан-Ниса»/12 аят."],["sc","img/word-92/image63.webp",294,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Раздел: О тех, кому завещается</b>"],["p","147/49 – Первый аят:"],["p","Всевышний Аллах сказал: «(Но кроме этого) вы (можете) делать добро своим сторонникам [другим верующим] (поддерживая с ними хорошие отношения, помогая им материально, завещая им что-либо,…)», сура «Аль-Ахзаб»/6 аят."],["p","148/50 – Второй аят:"],["p","Всевышний Аллах сказал: «А кто изменит это [завещание] [убавит долю завещанного или прибавит или скроет] после того, как услышал [достоверно узнал], то грех за это [за изменение] будет только на тех, которые изменяют это (а не на завещателе). Поистине, Аллах – слышащий, знающий!», сура «Аль-Бакара»/181 аят."],["sep",""],["sc","img/word-92/image64.webp",296,504,"f"],["c","Книга Наследства"],["h2","<b>Книга Наследства (1)</b>"],["h2","<b>Глава: Предписания</b>"]],[["p","149/1 – Первый аят:"],["p","Всевышний Аллах сказал: «Наставляет вас Аллах относительно ваших детей: мужчине (даётся) доля (наследства), подобная доле двух женщин. А если они [дети] – женщины, числом больше двух, то им (полагается) две трети того, что он [умерший] оставил. А если она [дочь] (только) одна, то ей – половина. А родителям его [умершего], каждому из двух – одна шестая того, что он оставил, если у него есть ребёнок. А если у него [у умершего] нет ребенка, и его наследниками являются его родители, то матери – одна треть (а отцу всё остальное). А если есть у него братья, то матери (достаётся) одна шестая (наследства). (И такое распределение наследственного имущества делается) после (исполнения) завещанного, которой он [умерший] завещает, или долга (который был на нём). Родители ваши или ваши дети – вы не знаете, кто из них ближе вам по пользе, (поэтому не отдавайте предпочтения одним над другими). (И это наставление) является предписанием от Аллаха. Поистине, Аллах знающий (и) мудрый! (11) И вам (о, мужчины) – половина того, что оставили ваши супруги [жёны], если у них нет ребёнка. А если у них [у ваших жён] есть ребёнок, то вам – четверть (имущества). (И такое распределение наследственного имущества делается) после (исполнения) завещанного, которой он [умерший] завещает, или долга (который был на нём). А им [вашим жёнам] – четверть того, что оставили вы (мужья), если у вас нет ребёнка. А если у вас есть ребенок, то им [вашим жёнам] – одна восьмая того (имущества), что вы оставили.  (И такое распределение наследственного имущества делается) после (исполнения) завещанного, которое вы завещаете, или долга (который есть на вас)."],["p","(1) Общее число аятов, которые привел Ибн Касим в книге Наследства – 8 аятов."],["sc","img/word-92/image65.webp",294,504,"f"]],[["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","которое вы завещаете, или долга (который есть на вас). А если мужчина оставляет наследство только по боковой линии, или женщина [у него или у неё нет родителей и детей], и у него (или у неё) есть брат (по матери) или сестра (по матери), то каждому из них обоих – одна шестая. А если их [братьев и сестёр по матери] больше этого, то они – соучастники в трети [треть имущества делится между ними поровну, независимо мужчины или женщины]. (И такое распределение наследственного имущества делается) после (исполнения) завещанного, которое завещается, или долга (который есть на умершем), не причиняя вреда, по наставлению от Аллаха. А Аллах – знающий (в чём благо для Его рабов) (и) сдержанный [не спешит с наказанием]! (12) Это [положения касающиеся сирот, женщин и наследства] – границы Аллаха [которые Он установил]. А кто повинуется Аллаху и Его посланнику (в том, что Он предписал для Своих рабов), того Он введёт в сады (Рая), (где) текут под ними [под дворцами и деревьями] реки, и они пребудут в них [в райских садах] вечно. И это [обретение такой награды] – великий успех! (13) А кто ослушается Аллаха и Его посланника и преступает Его границы [те, которые Он установил], того Он введёт в огонь (Ада) на вечное пребывание в нём, и для него – унижающее наказание. (14)», сура «Ан-Ниса»/11-14 аяты."],["p","150/2 – Второй аят:"],["p","Всевышний Аллах сказал: «И спрашивают они [люди] у тебя (о, Пророк) решения (в вопросах распределения наследства). Скажи (им): «Аллах даст вам решение [разъяснит положение] относительно такого умершего, (который) оставил наследство только по боковой линии [у него или у неё нет родителей и детей]. Если умрёт человек, (у которого) нет ребёнка, а есть у него сестра, то ей (полагается) половина того (имущества), что он оставил. И он [брат] наследует после неё (всё её имущество), если у неё нет ребенка. А если их [сестёр] – две, то им обеим – две трети того, что он [их брат] оставил. А если они [наследники] – братья (и сёстры), мужчины и женщины, то мужчине (полагается) (доля) (равная) доле двух женщин». Аллах даёт вам разъяснение (в вопросах распределения наследства), чтобы вы не впали в заблуждение (и даже в этом вопросе). А Аллах о всякой вещи [обо всём] знает!», сура «Ан-Ниса»/176 аят."],["h2","<b>Глава: О получении наследства непрямыми наследниками</b>"],["p","151/3 – Первый аят:"],["p","Всевышний Аллах сказал: «А если они [наследники] – братья (и сёстры), мужчины и женщины, то мужчине (полагается) (доля) (равная) доле двух женщин», сура «Ан-Ниса»/176 аят."],["sc","img/word-92/image66.webp",296,504,"f"],["c","Книга  Наследования"],["h2","<b>Глава: Наследование родственниками</b>"]],[["p","152/4 - Первый аят:"],["p","Всевышний Аллах сказал: «А обладатели же родства [верующие родственники] – одни из них близки к другим [более близки друг к другу, чем к другим верующим] (при получении наследства) по писанию Аллаха [по установленному Аллахом положению]», сура «Аль-Анфаль»/75 аят."],["p","153/5 – Второй аят: (1)"],["p","Всевышний Аллах сказал: «Мужчинам (даётся) доля (наследства) из того, что оставили родители и близкие родственники, и женщинам (тоже даётся) доля (наследства) из того, что оставили родители и близкие родственники», сура «Ан-Ниса»/7 аят."],["h2","<b>Глава: Отпущение раба</b>"],["p","154/6 – Первый аят:"],["p","Всевышний Аллах сказал: «Освобождение верующего раба», сура «Ан-Ниса»/92 аят."],["p","155/7 – Второй аят:"],["p","Всевышний Аллах сказал: «Отпустить раба (на свободу)», сура «Аль-Баляд»/1 аят."],["h2","<b>Глава: Записывание (договора о получении освобождения из рабства)</b>"],["p","156/8 – Первый аят:"],["p","Всевышний Аллах сказал: «А те, которые хотят записи (о свободе) [договориться об освобождении из рабства за определённое имущество], из тех, которыми овладели десницы ваши [из числа ваших рабов и рабынь], – заключайте (договор об освобождении) с ними, если знаете, что в них есть добро [благоразумие, способность зарабатывать самостоятельно и крепкая вера], и давайте (о, владельцы) им [вашим рабам, которые желают свободы] из достояния Аллаха то, что Он дал вам [помогите им, дав некоторое имущество из вашего закята или списав часть оговоренного имущества]», сура «Ан-Нур»/33 аят."],["p","(1) Данный аят отсутствует в издании «Основы вынесения шариатских постановлений»"],["sc","img/word-92/image67.webp",296,503,"f"],["c","Книга Бракосочетания"],["h2","<b>Книга Бракосочетания (1)</b>"],["p","157/1 – Первый аят:"],["p","Всевышний Аллах сказал: «То женитесь на (других) (из) тех, что приятны вам, женщинах – на двух, (или) на трёх, (или) на четырёх. А если боитесь, что не будете справедливы (между несколькими жёнами), то (женитесь) (лишь) на одной или на тех, которыми овладели ваши десницы (так как не является обязательным придерживаться полной справедливости между невольницами). Это [женитьба лишь на одной] – ближе, чтобы не уклониться (от справедливости)», сура «Ан-Ниса»/3 аят."]],[["p","158/2 – Второй аят:"],["p","Всевышний Аллах сказал: «И жените (о, верующие) безбрачных (мужчин и женщин) (как уже бывавших в супружестве, также и не бывавших) из вас [из числа верующих] и праведных [верующих] из числа невольников ваших и ваших невольниц [тех, которыми вы владеете]», сура «Ан-Нур»/32 аят."],["h2","<b>Раздел: О столпах бракосочетания</b>"],["p","159/3 – Первый аят:"],["p","Всевышний Аллах сказал: «Мы женили тебя на ней», сура «Аль-Ахзаб»/37 аят."],["p","(1) Общее число аятов, которые Ибн Касим приводит в книге Бракосочетания – 33 аята."],["sc","img/word-92/image68.webp",293,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Раздел: Об условии добровольного согласия</b>"],["p","160/4 – Первый аят:"],["p","Всевышний Аллах сказал: «(Относительно) того, что читается вам в Книге [Коране], – о сиротах из (числа) женщин», сура «Ан-Ниса»/127 аят."],["h2","<b>Раздел: Об опекуне</b>"],["p","161/5 – Первый аят:"],["p","Всевышний Аллах сказал: «И жените (о, верующие) безбрачных (мужчин и женщин) (как уже бывавших в супружестве, также и не бывавших) из вас [из числа верующих] и праведных [верующих] из числа невольников ваших и ваших невольниц [тех, которыми вы владеете]», сура «Ан-Нур»/32 аят."],["p","162/6 – Второй аят:"],["p","Всевышний Аллах сказал: «Женитесь же на них [на женщинах] с дозволения их семей», сура «Ан-Ниса»/25 аят."],["h2","<b>Раздел: О соответствии (супругов друг другу)</b>"],["p","163/7 – Первый аят:"],["p","Всевышний Аллах сказал: «Поистине самый почтенный [лучший и достойный в этом мире и Вечной жизни] из вас пред Аллахом – самый остерегающийся (грехов и наказания Аллаха)», сура «Аль-Худжурат»/13 аят."],["h2","<b>Глава: На ком запрещено жениться</b>"],["p","164/8 – Первый аят:"],["p","Всевышний Аллах сказал: «Запрещены вам ваши матери [мать, бабушка,...], и ваши дочери [дочери, внучки,…], и ваши (родные) сёстры [сестра по отцу и по матери, сестра по отцу и сестра по матери],"],["sc","img/word-92/image69.webp",296,504,"f"],["c","Книга Бракосочетания"]],[["p","и ваши тётки (со стороны отца), и ваши тётки (со стороны матери), и дочери брата, и дочери сестры, и ваши матери, которые вас вскормили [молочные матери], и ваши сёстры по кормлению [молочные сёстры], и матери ваших жён (независимо имели вы с ними близость или не имели), и ваши падчерицы, которые (находятся) под вашим покровительством [заботой и воспитанием] от ваших жён, к которым вы уже вошли [имели близость]; а если вы ещё не вошли к ним [не имели близость], то нет греха на вас (жениться на ваших падчерицах, после развода с их матерями или их смерти); и жёны ваших сыновей, которые произошли от ваших поясниц [родных, а не приёмных сыновей]; и (также) (запрещено) объединять двух сестёр [одновременно жениться на двух сёстрах, и даже молочных], если только это не произошло раньше [до этого запрещения]. Поистине, Аллах прощающий (тех, кто грешит, если они каются) (и) милосердный (так как Он не возлагает ничего, кроме только возможного)!», сура «Ан-Ниса»/23-24 аят."],["p","165/9 – Второй аят:"],["p","Всевышний Аллах сказал: «И не женитесь на тех женщинах, на которых (уже) были женаты ваши отцы, разве только это произошло раньше [до этого запрещения]. Поистине, это [такая женитьба] является мерзостью, ненавистным (деянием) и скверным путём!», сура «Ан-Ниса»/22 аят."],["p","166/10 – Третий аят:"],["p","Всевышний Аллах сказал: «Прелюбодей (из числа верующих) женится только на (подобной себе) прелюбодейке или многобожнице, а прелюбодейка (из числа верующих) – на ней женится только прелюбодей или многобожник. И запрещено это [такое супружество] для верующих», сура «Ан-Нур»/3 аят."],["sc","img/word-92/image70.webp",302,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","167/11 – Четвертый аят:"]],[["p","Всевышний Аллах сказал: «Если же он [муж] дал ей развод (в третий раз), то она не дозволяется ему после этого, пока она не выйдет замуж за другого (мужчину)», сура «Аль-Бакара»/130 аят."],["p","168/12 – Пятый аят:"],["p","Всевышний Аллах сказал: «И не женитесь на многобожницах, пока они не уверуют [пока не примут Ислам]», сура «Аль-Бакара»/221 аят."],["p","169/13 – Шестой аят:"],["p","Всевышний Аллах сказал: «И не выдавайте (верующих рабынь и верующих свободных) замуж за многобожников, пока они не уверуют», сура «Аль-Бакара»/221 аят."],["p","170/14 – Седьмой аят:"],["p","Всевышний Аллах сказал: «И целомудренных [супружески верных] из тех, кому даровано Писание до вас [на иудейках и христианках]», сура «Аль-Маида»/5 аят."],["h2","<b>Глава: Брак неверующих</b>"],["p","171/15 – Первый аят:"],["p","Всевышний Аллах сказал: «И Аллах привёл примером для тех, которые уверовали, жену Фараона (чтобы показать, что истинно верующим не навредит их вынужденное пребывание даже среди самых худших неверующих)», сура «Ат-Тахрим»/11 аят."],["p","172/16 – Второй аят:"],["p","Всевышний Аллах сказал: «И жена его – носильщица дров (тоже будет наказана вместе с ним)», сура «Аль-Масад»/4 аят."],["sc","img/word-92/image71.webp",347,510,"f"],["c","Книга Бракосочетания"],["p","173/17 – Третий аят:"],["p","Всевышний Аллах сказал: «Они [верующие женщины] не дозволены им [неверующим мужчинам], и те [неверующие мужчины] не дозволяются им [верующим женщинам]. И отдавайте им [их бывшим мужьям] то, что они израсходовали (на своих бывших жён) (в качестве брачного дара). И не (будет) греха на вас (о, верующие мужчины), если вы женитесь на них [на переселившихся верующих женщинах], когда дадите им их плату [брачный дар]. И не держитесь за (брачные) узы с неверующими женщинами», сура «Аль-Мумтахана»/10 аят."],["h2","<b>Глава: Брачный дар</b>"],["p","174/18 – Первый аят:"],["p","Всевышний Аллах сказал: «Стремясь своим имуществом, соблюдая целомудрие [оберегая свою супружескую верность], не распутничая [не совершая прелюбодеяния]», сура «Ан-Ниса»/24 аят."]],[["p","175/19 – Второй аят:"],["p","Всевышний Аллах сказал: «И давайте женщинам их (обязательный) брачный дар от чистой души. Если же они [ваши жёны] соблаговолят чем-нибудь из этого [из брачного дара] для вас [позволят пользоваться], то кушайте это наслаждаясь и во благо», сура «Ан-Ниса»/4 аят."],["p","176/20 – Третий аят:"],["p","Всевышний Аллах сказал: «Давайте им [вашим жёнам] их награду [брачный дар] по (обязательному) установлению (от Аллаха)», сура «Ан-Ниса»/24 аят."],["p","177/21 – Четвертый аят:"],["p","Всевышний Аллах сказал: «А если вы (о, мужья) захотели замены одной супруги другой [развестись с одной и жениться на другой] и одной из них [разводимой] дали кинтар [большое количество] (имущества), то не отбирайте из него [из того имущества] ничего. Разве вы станете отбирать это, поступая лживо и совершая явный грех? [До Ислама, некоторые мужья, когда разводились с жёнами, ложно обвиняли их в прелюбодеянии, и оставляли брачный дар и любое другое имущество жены у себя]. (20) И как вы (о, мужчины) можете отбирать это [брачный дар ваших жён], когда вы сошлись друг с другом [имели близость] и они [жёны ваши] взяли с вас суровый завет (о том, что вы будете удерживать их у себя, согласно принятому среди людей, либо отпускать их, соблюдая их права и не причиняя им вреда)? (21)», сура «Ан-Ниса»/20-21 аяты."],["sc","img/word-92/image72.webp",331,512,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","178/22 – Пятый аят:"],["p","Всевышний Аллах сказал: «(Их отец) сказал (Мусе): «Поистине, я хочу женить тебя на одной из этих двух моих дочерей с тем (условием), что ты наймёшься ко мне (пасти скот) на восемь лет. А если ты завершишь десятью (годами), так это (будет) (искренним благодеянием) от тебя. И я не хочу затруднять тебя (сделав срок в десять лет). Ты найдёшь меня, если пожелает Аллах, из числа праведных [я буду хорошим товарищем и исполню то, что сказал]». (27) Сказал он [Муса]: «Это [то, что ты сказал] – между мной и тобой; какой бы из сроков [восемь или десять] я ни выполнил, то не (должно быть) притеснения для меня [не нужно будет просить меня сделать больше], и Аллах – покровитель [свидетель и хранитель] тому, что мы говорим!», сура «Аль-Касас»/27-28 аяты."],["h2","<b>Раздел: Вступление женщины в брак без установления махра</b>"]],[["p","179/23 – Первый аят:"],["p","Всевышний Аллах сказал: «Не будет греха на вас (о, мужчины), если вы дадите развод жёнам (после заключения брачного союза), пока не коснулись их [пока не имели близость с ними] и (пока) не установили им обязательное вознаграждение [пока не назвали размер махра – брачного дара]. И наделяйте их [женщин] дарами (когда разводитесь с ними) (чтобы сгладить обиду), – на состоятельном [богатом] – своя мера (возможностей в одаривании), а на бедном – своя мера (возможностей), – как наделяют согласно принятому [шариату], как подобает (поступать) добродеющим (по отношению к разводимым женщинам)», сура «Аль-Бакара»/236 аят."],["h2","<b>Глава: Как следует обходиться с женами</b>"],["p","180/24 – Первый аят:"],["p","Всевышний Аллах сказал: «И обходитесь с ними [с женами] достойно [с любовью, уважением и исполнением их прав]. Если же вы не любите их [ваших жён], то (терпите), (так как) может быть, что-либо вам и нелюбимо, а Аллах устроил в этом великое благо», сура «Ан-Ниса»/9 аят."],["sc","img/word-92/image73.webp",296,504,"f"],["c","Книга Бракосочетания"],["p","181/25 – Второй аят:"],["p","Всевышний Аллах сказал: «И у них [у женщин, как разведенных, так и неразведённых] – то же самое [есть такие же права], что и (обязанности возложенные) на них [женщинах], согласно принятому (по установлению Аллаха). А мужья имеют над ними [жёнами] – степень [обязанность обеспечивать жену и право дать развод]», сура «Аль-Бакара»/228 аят."],["p","182/26 – Третий аят:"],["p","Всевышний Аллах сказал: «Отдаляйтесь же от женщин [не имейте близость с ними] при месячных», сура «Аль-Бакара»/222 аят."],["h2","<b>Раздел: О разделении долей (каждой из жен)</b>"],["p","183/27 – Первый аят:"],["p","Всевышний Аллах сказал: «Не уклоняйтесь же (от той, которую вы любите меньше) всем уклонением, чтобы не оставить её словно висящей [такой, которая не является ни женой, ни разведённой]», сура «Ан-Ниса»/129 аят."]],[["p","184/2 – Второй аят:"],["p","Всевышний Аллах сказал: «А если боитесь, что не будете справедливы (между несколькими жёнами), то (женитесь) (лишь) на одной или на тех, которыми овладели ваши десницы (так как не является обязательным придерживаться полной справедливости между невольницами). Это [женитьба лишь на одной] – ближе, чтобы не уклониться (от справедливости)», сура «Ан-Ниса»/3 аят."],["h2","<b>Раздел: О непокорности (жен)</b>"],["p","185/29 – Первый аят:"],["p","Всевышний Аллах сказал: «А тех (женщин), непокорности которых вы опасаетесь, увещевайте и покидайте их на (суружеских) ложах и (если это не поможет, то) побивайте их (не причиняя вреда). И если они [непокорные женщины] станут покорны вам, то не ищите пути против них, – поистине, Аллах – высочайший (и) великий (и Он отомстит тем, которые чинят зло и несправедливость по отношению к другим)!», сура «Ан-Ниса»/34 аят."],["sc","img/word-92/image74.webp",294,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","186/30- Второй аят:"],["p","Всевышний Аллах сказал: «И если женщина станет бояться от своего мужа (проявления) неприязни [когда он, из-за её старости, охладеет к ней] или уклонения [и при этом он не будет смотреть и не обращать на неё внимания], то не (будет) греха на них двоих [на муже и жене], чтобы они устроили между собой согласие (в вопросах расходования на неё и распределения ночей). И (ведь) согласие – лучше. И при душах (постоянно) пребывает скупость. А если вы будете добродетельны (со своими жёнами) и остерегаться (наказания Аллаха) (исполняя Его повеления и отстраняясь от того, что Он запретил), то, поистине, Аллах сведущ в том, что вы делаете», сура «Ан-Ниса»/128 аят."],["p","187/31 – Третий аят:"]],[["p","Всевышний Аллах сказал: «А если вы (о, близкие супругов) боитесь разлада между обоими [супругами], то пошлите судью из его семьи и судью из её семьи (чтобы они решили в чём благо для супругов); если они [две судьи] пожелают примирения, то Аллах поможет им [супругам]. Поистине, Аллах – знающий (и) всеведающий!», сура «Ан-Ниса»/35 аят."],["h2","<b>Глава: Развод по инициативе женщины</b>"],["p","188/32 – Первый аят:"],["p","Всевышний Аллах сказал: И не дозволяется вам (о, мужья) брать хоть что-либо из того, что вы им [жёнам] даровали (как например брачный дар и подобное этому), кроме, как только если они оба (супруга) (будут) бояться не выполнить ограничений Аллаха (в вопросах соблюдения супружеских прав). (И в таком случае оба супруга представляют свою ситуацию ответственным лицам или людям, которые могут помочь разрешить её). А если вы [ответственные лица] боитесь, что они оба [супруг и супруга] не выполнят ограничений Аллаха, то не будет греха на них [на муже и жене] в том, чем она [супруга] себя выкупит [дозволяется женщине предложить мужу определённое имущество в обмен на развод]», сура «Аль-Бакара»/229 аят."],["p","189/33 – Второй аят:"],["p","Всевышний Аллах сказал: «И не препятствуйте (о, мужья) им [женщинам] уносить часть того, что вы им даровали (в качестве брачного дара) (когда вы не желаете продолжать жить с ними), разве что они [женщины] совершат очевидную мерзость [прелюбодеяние]», сура «Ан-Ниса»/19 аят."],["sc","img/word-92/image75.webp",326,506,"f"],["c","Книга Развода"],["h2","<b>Книга Развода (1)</b>"],["p","190/1 – Первый аят:"],["p","Всевышний Аллах сказал: «А когда вы (о, мужья) даёте развод жёнам, и когда они [разведённые женщины] достигают своего предела [приближается срок завершения их ‘идды], то удерживайте их [возвращайте  до истечения срока ‘идды] согласно принятому [добрым образом и с намерением соблюдать их права по шариату и как принято среди людей] или отпускайте их [позвольте, чтобы вышел срок их ‘идды] согласно принятому, но не удерживайте их насильно [со злым умыслом], преступая [посягая на их права]. А кто сделает это, тот откажется злодеем по отношению к самому себе (подвергая себя к наказанию Аллаха). И не насмехайтесь над знамениями Аллаха [относитесь к ним с полной серьёзностью]. И помните благодать, (которую) Аллах оказал вам [даровал Веру и разъяснил положения Своего Закона] и то, что Он ниспослал вам из Писания [Коран] и мудрости [Сунну], увещевая вас этим; и остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и, сторонясь того, что Он запретил) и знайте, что Аллах о каждой вещи [обо всём] знает!», сура «Аль-Бакара»/231 аят."],["h2","<b>Раздел: О сроке выжидания</b>"]],[["p","191/2 – Первый аят:"],["p","Всевышний Аллах сказал: «О, Пророк (и его община), когда вы даёте жёнам развод, то разводитесь с ними по установленныму для них сроку», сура «Ат-Талак»/1 аят."],["p","192/3 – Второй аят:"],["p","Всевышний Аллах сказал: «А разведенные (женщины, у которых бывают месячные) выжидают [обязаны ждать] (после развода, не выходя замуж за другого и удерживая) самих себя (от такого замужества) три периода [либо три месячных, либо три чистых периода] (чтобы удостовериться в том, что они не беременны) и не разрешается им [разведённым женщинам] скрывать то, что сотворил Аллах в их утробах [есть ли беременность или когда происходят месячные], если они [эти женщины] (истинно) веруют в Аллаха и в Последний День."],["p","(1) Общее число аятов, которые Ибн Касим приводит в книге Развода – 13 аятов."],["sc","img/word-92/image76.webp",293,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","А мужья их имеют больше прав вернуть их [разведённую жену] при этом [при ‘идде – послеразводном сроке], если они желают уладить (отношения) [снова объединиться, а не для причинения вреда жене с целью наказания]. И у них [у женщин, как разведенных, так и неразведённых] – то же самое [есть такие же права], что и (обязанности возложенные) на них [женщинах], согласно принятому (по установлению Аллаха). А мужья имеют над ними [жёнами] – степень [обязанность обеспечивать жену и право дать развод]. А Аллах – величественный (в Своём владычестве), мудрый (в Своих решениях и повелениях)! (228) (Возвратный) развод (может даваться только) два раза: (после него) [возвратного развода] – либо удержание (жены у себя) [возврат её], согласно принятому (у людей), либо отпустить с благодеянием [соблюдая её права и не причиняя ей вреда]. И не дозволяется вам (о, мужья) брать хоть что-либо из того, что вы им [жёнам] даровали (как например брачный дар и подобное этому), кроме, как только если они оба (супруга) (будут) бояться не выполнить ограничений Аллаха (в вопросах соблюдения супружеских прав). (И в таком случае оба супруга представляют свою ситуацию ответственным лицам или людям, которые могут помочь разрешить её). А если вы [ответственные лица] боитесь, что они оба [супруг и супруга] не выполнят ограничений Аллаха, то не будет греха на них [на муже и жене] в том, чем она [супруга] себя выкупит [дозволяется женщине предложить мужу определённое имущество в обмен на развод]. Таковы границы Аллаха [обязательные установления] (которые отделяют дозволенное от запретного), не преступайте же их [границы], а если кто преступает границы Аллаха, те – злодеи (по отношению к самим себе). (229) Если же он [муж] дал ей развод (в третий раз), то она не дозволяется ему после этого, пока она не выйдет замуж за другого (мужчину). А если (новый муж) даст ей развод (или умрёт), (и она выдержит ‘идду – послеразводный срок) то не будет греха на них [на прежнем муже и жене], что они (вдвоём) вернутся [снова заключат супружеский союз с новым махром – брачным даром], если они (двое) полагают, что выполнят ограничения [установления] Аллаха [права и обязанности супругов]. {Возврат к прежнему мужу будет возможным только, если она выйдет замуж добровольно, не с целью дозволения её прежнему мужу, и если она будет иметь близость с новым мужем.} И вот таковы границы Аллаха [Его установления], которые Он разъясняет людям, которые знают (Его постановления и границы, потому что в этом для них есть польза) (230)», сура «Аль-Бакара»/228-230 аяты."],["h2","<b>Раздел: О Аль-Кинайа</b>"]],[["p","193/4 – Первый аят:"],["p","Всевышний Аллах сказал: «О, Пророк! Скажи своим жёнам (которые собрались у тебя, прося увеличить расходы на них): «Если вы желаете земной жизни и ее прикрас, то приходите: я дам вам наделю вас благами [дам вам то, что есть у меня] и отпущу вас прекрасным способом [без причинения вам вреда]. (28) А если вы хотите (довольства) Аллаха и (довольства) Его Посланника и Обители Вечности [хорошей награды в Вечной жизни], то (проявляйте терпение и знайте, что) Аллах уготовал искренне добродеющим из вас великую награду (по сравнению с которой, земные блага кажутся ничтожными). (29)», сура «Аль-Ахзаб»/28-29 аяты."],["h2","<b>Раздел: О клятве</b>"],["p","194/5 – Первый аят:"],["p","Всевышний Аллах сказал: «Уже установил Аллах для вас (о, верующие) путь освобождения от ваших клятв [определил искупление за них: накормить десять бедняков, или одеть их, или освободить одного раба, а кто не сможет сделать этого, то постится три дня]», сура «Ат-Тахрим»/2 аят."],["sc","img/word-92/image77.webp",296,502,"f"],["c","Книга Развода"],["p","195/6 – Второй аят:"],["p","Всевышний Аллах сказал: «Это [то, что было перечислено] – искупление ваших клятв, которыми вы поклялись. Охраняйте же ваши клятвы [удерживайтесь от клятв; или исполняйте же, если поклялись; или совершайте искупление]!», сура «Аль-Маида»/89 аят."],["h2","<b>Глава: О различиях между сроками выжидания при разводах</b>"],["p","196/7 – Первый аят:"],["p","Всевышний Аллах сказал: «Если же он [муж] дал ей развод (в третий раз), то она не дозволяется ему после этого, пока она не выйдет замуж за другого (мужчину)», сура «Аль-Бакара»/230 аят."],["h2","<b>Глава: Привязывание развода к условиям</b>"],["p","197/8 – Первый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Если вы женитесь на верующих (женщинах) [заключите с ними брачный союз], а потом разведётесь с ними», сура «Аль-Ахзаб»/49 аят."],["h2","<b>Глава: О возвращении (жены)</b>"]],[["p","198/9 – Первый аят:"],["p","Всевышний Аллах сказал: «О, Пророк (и его община), когда вы даёте жёнам развод, то разводитесь с ними по установленныму для них сроку, и отсчитывайте этот срок, и остерегайтесь (наказания) Аллаха, Господа вашего (также и при разводе) [выполняйте то, что Он повелел и прекратите совершать то, что Он запретил]! Не выгоняйте их [женщин] из их домов [где они проживают],"],["sc","img/word-92/image78.webp",295,518,"f"],["p","и пусть они [женщины] (сами тоже) не выходят [пусть не покидают дом], если только они не совершат явную мерзость [как прелюбодеяние]. Таковы границы (установленные) Аллахом. А кто преступает границы (установленные) Аллахом, тот (значит) причил самому себе зло. Ты (о, разводящийся мужчина) не знаешь, может быть, Аллах произведёт после этого [развода] какое-нибудь дело (что ты решишь вернуть её обратно). (1) А когда они [разведённые женщины] достигнут своего предела [когда приблизится срок завершения их ‘идды], то удерживайте их (о, мужья) [возвращайте  до истечения срока ‘идды] согласно принятому [добрым образом и с намерением соблюдать их права по шариату и как принято среди людей] или расставайтесь с ними [позвольте, чтобы вышел срок их ‘идды] согласно принятому [не причиняя им вреда]. И (для возврата разводимой жены или же окончательного расставания с ней) призовите в свидетели двух справедливых (мужчин) из числа вас [верующих] и (о, свидетели) исполняйте свидетельство (только) ради Аллаха (а не для чего-либо другого). Этим [тем, что Аллах повелел] увещается тот, кто верует в Аллаха и в Последний день [в День Суда]. А кто будет остерегаться (наказания) Аллаха [исполнять Его повеления и отстраняться от Его запретов], тому Он сделает выход (из любого затруднительного положения) (2) и Он даст ему [остерегающемуся] пропитание [облегчит получение удела], откуда он и не рассчитывает. И кто полагается на Аллаха [полностью вверяет свое дело Ему], то для того Он достаточен [Он избавит его от всего, что его заботит и беспокоит] (как в этом мире, так и в Вечной жизни). (Ведь) поистине Аллах доводит Свое дело (до конца) [никто Ему не может препятствовать и Он не устанет от просьб]. (И) уже установил Аллах для каждой вещи меру [определил сроки, место, размер и остальные пределы для всего]», сура «Ат-Талак»/1-3 аяты."]]];
